package org.zhixiaoce.aperture.test;

import android.app.*;import android.content.Intent;import android.graphics.Bitmap;import android.media.MediaPlayer;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;

/** System-injected input regression, never included in product assets. */
public final class RemoteRegressionRunner extends Instrumentation {
    private Activity activity;private Bundle args;private JSONArray checks=new JSONArray(),images=new JSONArray();
    interface Task {void run()throws Exception;} interface Read<T>{T get()throws Exception;}
    private void ui(Task w)throws Exception{AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{w.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new Exception(error.get());}
    private <T>T read(Read<T> w)throws Exception{AtomicReference<T> v=new AtomicReference<>();ui(()->v.set(w.get()));return v.get();}
    private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
    private Object call(Object o,String n,Class<?>[] t,Object...v)throws Exception{Method m=o.getClass().getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o,v);}
    private void until(Read<Boolean> w,String why)throws Exception{long end=SystemClock.uptimeMillis()+90000;while(SystemClock.uptimeMillis()<end){if(w.get())return;SystemClock.sleep(120);}throw new AssertionError(why);}
    private void check(boolean ok,String s){if(!ok)throw new AssertionError(s);checks.put(s);Bundle b=new Bundle();b.putString("check",s);sendStatus(0,b);}
    private void walk(View v,List<View> a){a.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),a);}
    private List<View> tree(){List<View> a=new ArrayList<>();walk(activity.getWindow().getDecorView(),a);return a;}
    private View named(String s){for(View v:tree())if(v instanceof TextView&&s.equals(((TextView)v).getText().toString()))return v;return null;}
    private Activity open(String view){Intent i=new Intent();i.setClassName(getTargetContext(),"org.zhixiaoce.aperture.CinemaActivity");i.putExtra("view",view);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);return startActivitySync(i);}
    private void key(int code)throws Exception{until(()->read(()->activity.hasWindowFocus()),"window focus before key "+code);sendKeyDownUpSync(code);SystemClock.sleep(250);}
    private void touchHeader(Object panel)throws Exception{int[] at=read(()->{View v=(View)field(panel,"heading");int[] xy=new int[2];v.getLocationOnScreen(xy);return new int[]{xy[0]+v.getWidth()/2,xy[1]+v.getHeight()/2};});long now=SystemClock.uptimeMillis();MotionEvent d=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,at[0],at[1],0),u=MotionEvent.obtain(now,now+60,MotionEvent.ACTION_UP,at[0],at[1],0);sendPointerSync(d);sendPointerSync(u);d.recycle();u.recycle();SystemClock.sleep(200);}
    private boolean playing()throws Exception{return read(()->Boolean.TRUE.equals(field(activity,"prepared"))&&field(activity,"player")!=null&&((MediaPlayer)field(activity,"player")).isPlaying());}
    private void picture(String n)throws Exception{SystemClock.sleep(250);Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new IOException("system screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"s74-"+n+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();images.put(n);}
    @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
    @Override public void onStart(){JSONObject report=new JSONObject();Bundle result=new Bundle();boolean passed=false;try{
        activity=open("settings");Class<?> http=getTargetContext().getClassLoader().loadClass("org.zhixiaoce.aperture.CinemaHttp");Constructor<?> constructor=http.getDeclaredConstructor();constructor.setAccessible(true);Object config=call(constructor.newInstance(),"importUrl",new Class[]{String.class,boolean.class},args.getString("fixture")+"/pack.json",true);
        ui(()->{call(field(activity,"vault"),"importConfig",new Class[]{config.getClass()},config);activity.finish();});activity=open("series");
        until(()->read(()->Boolean.TRUE.equals(field(activity,"browseActive"))&&((List<?>)field(activity,"sectionItems")).size()>0),"catalogue ready");
        check(read(()->named("返回片单")==null),"section opens catalogue without auto-opening first detail");key(KeyEvent.KEYCODE_DPAD_CENTER);
        until(()->read(()->{for(View v:tree())if(v.getClass().getSimpleName().equals("CinemaEpisodeGrid"))return true;return false;}),"detail episodes ready");
        check(read(()->{int episodes=0;for(View v:tree()){if(v instanceof TextView&&((TextView)v).getText().toString().contains("相似影片"))return false;if(v instanceof Button&&((Button)v).getText().toString().startsWith("第")){TextView t=(TextView)v;episodes++;if(t.getMaxLines()<10||t.getEllipsize()!=null||t.getLayout()==null||t.getLayout().getLineEnd(t.getLineCount()-1)!=t.length())return false;}}return episodes==20;}),"detail has 20 full-title episodes per group, no related film section or ellipsis");
        ui(()->{View b=named("第1集：穿越星河与山海的漫长旅程，家人重逢之前的特别记录（完整节目标题）");b.requestFocus();b.requestRectangleOnScreen(new android.graphics.Rect(0,0,b.getWidth(),b.getHeight()));});SystemClock.sleep(250);picture("detail");key(KeyEvent.KEYCODE_DPAD_CENTER);until(this::playing,"VOD started");
        check(read(()->activity.getCurrentFocus()==field(activity,"videoSurface")),"playback initially focuses video, not pause");
        long before=read(()->(long)((MediaPlayer)field(activity,"player")).getCurrentPosition());key(KeyEvent.KEYCODE_DPAD_RIGHT);until(()->read(()->((MediaPlayer)field(activity,"player")).getCurrentPosition()>before+5000),"seek right applies");key(KeyEvent.KEYCODE_DPAD_LEFT);check(playing(),"default left/right seeks without pausing");
        key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->field(activity,"choicePanel")!=null),"OK opens episode picker");check(playing(),"OK opens episodes while playback continues");Object picker=read(()->field(activity,"choicePanel"));touchHeader(picker);key(KeyEvent.KEYCODE_DPAD_DOWN);
        check(read(()->((Integer)field(picker,"selected"))==1),"system Down selects next episode after touch");picture("episodes");SystemClock.sleep(6000);check(read(()->field(activity,"choicePanel")==picker),"episode picker stays open while reading");key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->((Integer)field(activity,"playingIndex"))==1)&&playing(),"selected episode plays");key(KeyEvent.KEYCODE_DPAD_CENTER);final Object selectedPicker=read(()->field(activity,"choicePanel"));
        check(read(()->((Integer)field(selectedPicker,"selected"))==1),"picker reopens on current episode");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(read(()->((Integer)field(selectedPicker,"selected"))==20),"episode group navigates in place");key(KeyEvent.KEYCODE_BACK);check(read(()->field(activity,"choicePanel")==null&&!activity.isFinishing()),"Back closes picker before exiting playback");
        ui(()->activity.finish());activity=open("live");until(this::playing,"live started");key(KeyEvent.KEYCODE_DPAD_CENTER);Object channels=read(()->field(activity,"livePanel"));check(read(()->Boolean.TRUE.equals(call(channels,"open",new Class[]{}))),"live OK opens channels even when controls were visible");touchHeader(channels);key(KeyEvent.KEYCODE_DPAD_DOWN);
        check(read(()->((Integer)field(channels,"selected"))==1),"first system Down selects next channel after touch");picture("channels");SystemClock.sleep(6000);check(read(()->Boolean.TRUE.equals(call(channels,"open",new Class[]{}))),"channel picker does not auto-close while browsing");key(KeyEvent.KEYCODE_DPAD_CENTER);until(()->read(()->((Integer)field(activity,"playingIndex"))==1)&&playing(),"selected live channel plays");
        key(KeyEvent.KEYCODE_DPAD_DOWN);until(()->read(()->((Integer)field(activity,"playingIndex"))==2)&&playing(),"direct Down changes live channel");key(KeyEvent.KEYCODE_CHANNEL_UP);until(()->read(()->((Integer)field(activity,"playingIndex"))==3)&&playing(),"channel key changes live channel");
        check(read(()->{View stage=(View)field(activity,"playerStage");return stage.getWidth()==activity.getWindow().getDecorView().getWidth()&&stage.getHeight()==activity.getWindow().getDecorView().getHeight();}),"video stage fills window; aspect ratio retained");picture("player");passed=true;
    }catch(Throwable e){try{report.put("error",e.toString());if(activity!=null)picture("failure");}catch(Exception ignored){}}
    try{report.put("passed",passed).put("checks",checks).put("images",images).put("systemInput","Instrumentation.sendKeyDownUpSync and sendPointerSync via Android InputManager; no Activity.dispatchKeyEvent in this runner").put("emulator",true).put("xiaomiHardware",false).put("syntheticMediaFixture",true);try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"s74-report.json"))){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("report",report.toString());}catch(Exception ignored){}
    if(activity!=null)try{ui(()->activity.finish());}catch(Exception ignored){}finish(passed?-1:0,result);}
}
